//! Gap 8 / T-9: the committed fuzz corpus, replayed deterministically.
//!
//! `fuzz/corpus/<target>/` holds two kinds of files:
//!
//! * `seed-*` are valid encodings (generated by `regenerate_seed_corpus` below,
//!   so libFuzzer starts from structure-aware inputs).
//! * `regress-*` are hand-written inputs that pin a bug that was found (or a
//!   structural attack class). See `fuzz/regression/README.md` for the
//!   bug -> file -> test mapping.
//!
//! `corpus_replay_*` runs EVERY committed file through the same body libFuzzer
//! calls. It needs no nightly toolchain, so it runs in `cargo test --workspace`
//! on every push. It is a regression net, NOT coverage-guided fuzzing.

use std::panic::{catch_unwind, AssertUnwindSafe};
use std::path::PathBuf;

use crate::fuzz_bodies::ALL;

fn corpus_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fuzz/corpus")
}

fn files_for(target: &str) -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = std::fs::read_dir(corpus_root().join(target))
        .map(|rd| {
            rd.filter_map(|e| e.ok())
                .map(|e| e.path())
                .filter(|p| p.is_file())
                .collect()
        })
        .unwrap_or_default();
    v.sort();
    v
}

fn name_of(p: &std::path::Path) -> String {
    p.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default()
}

#[test]
fn corpus_replay_every_committed_input_runs_clean() {
    let mut total = 0usize;
    for (target, body) in ALL {
        let files = files_for(target);
        assert!(
            !files.is_empty(),
            "fuzz/corpus/{target}/ is missing or empty"
        );
        for f in files {
            let data = std::fs::read(&f).unwrap_or_default();
            let r = catch_unwind(AssertUnwindSafe(|| body(&data)));
            assert!(
                r.is_ok(),
                "corpus file {} made `{target}` panic",
                f.display()
            );
            total += 1;
        }
    }
    assert!(
        total >= 40,
        "expected a substantial committed corpus, found {total} files"
    );
}

#[test]
fn corpus_has_seed_and_regression_inputs_for_every_target() {
    for (target, _) in ALL {
        let names: Vec<String> = files_for(target).iter().map(|p| name_of(p)).collect();
        assert!(
            names.iter().any(|n| n.starts_with("seed-")),
            "{target}: no seed-* input"
        );
        assert!(
            names.iter().any(|n| n.starts_with("regress-")),
            "{target}: no regress-* input"
        );
    }
}

/// The specific bug-pinning inputs that must never be deleted.
#[test]
fn corpus_contains_the_named_bug_regressions() {
    let need: &[(&str, &str)] = &[
        // Merkle: bounds check found by the JSON-structure mutator (peak_index).
        ("merkle_proof_json", "regress-peak-index-out-of-range.json"),
        ("merkle_proof_json", "regress-peak-index-u64-max.json"),
        // Merkle: bag_peaks on an empty peak list.
        ("merkle_proof_json", "regress-empty-peaks.json"),
        ("merkle_proof_json", "regress-leaf-count-u64-max.json"),
        // Structural attack classes that reach the wire parsers.
        ("wire_message_json", "regress-deep-nesting.json"),
        ("audit_log_json", "regress-seq-u64-max.json"),
        ("commitment_decode", "regress-max-points-plus-one.bin"),
        ("invoice_commitment_decode", "regress-bad-version.bin"),
    ];
    for (target, file) in need {
        assert!(
            corpus_root().join(target).join(file).is_file(),
            "missing committed regression input fuzz/corpus/{target}/{file}"
        );
    }
}

/// Every valid `seed-*` for a decoder must actually DECODE (otherwise the seed
/// is useless to the fuzzer and the "canonical round-trip" assertion in the
/// body never runs on a success path).
#[test]
fn corpus_decoder_seeds_are_actually_valid_encodings() {
    use quorum_core::{scalar_from_bytes, Commitment, Signature};
    for p in files_for("commitment_decode")
        .iter()
        .filter(|p| name_of(p).starts_with("seed-"))
    {
        let d = std::fs::read(p).unwrap_or_default();
        assert!(
            Commitment::from_bytes(&d).is_ok(),
            "{} should decode",
            p.display()
        );
    }
    for p in files_for("signature_decode")
        .iter()
        .filter(|p| name_of(p).starts_with("seed-"))
    {
        let d = std::fs::read(p).unwrap_or_default();
        let arr: [u8; 96] = d.as_slice().try_into().expect("96-byte seed");
        assert!(
            Signature::from_bytes(&arr).is_ok(),
            "{} should decode",
            p.display()
        );
    }
    for p in files_for("scalar_decode")
        .iter()
        .filter(|p| name_of(p).starts_with("seed-"))
    {
        let d = std::fs::read(p).unwrap_or_default();
        let arr: [u8; 32] = d.as_slice().try_into().expect("32-byte seed");
        assert!(
            scalar_from_bytes(&arr).is_some(),
            "{} should decode",
            p.display()
        );
    }
    for p in files_for("invoice_commitment_decode")
        .iter()
        .filter(|p| name_of(p).starts_with("seed-"))
    {
        let d = std::fs::read(p).unwrap_or_default();
        let arr: [u8; 65] = d.as_slice().try_into().expect("65-byte seed");
        assert!(ciphersettle_core::InvoiceCommitment::from_bytes(&arr).is_ok());
    }
}

/// Writes the `seed-*` files. Run manually when the wire formats change:
///   cargo test -p quorum_adversarial -- --ignored regenerate_seed_corpus
/// then commit the result. Deterministic (seeded RNG).
#[test]
#[ignore]
fn regenerate_seed_corpus() {
    use ciphersettle_core::MerkleLog;
    use quorum_audit::{AuditEvent, AuditLog};
    use quorum_core::{scalar_to_bytes, DkgSession, Message, Poly, SignatureShare};
    use rand::{rngs::StdRng, SeedableRng};

    let root = corpus_root();
    let mut rng = StdRng::seed_from_u64(0x5EED_C0DE);
    let put = |target: &str, name: &str, bytes: &[u8]| {
        let dir = root.join(target);
        std::fs::create_dir_all(&dir).expect("mkdir corpus dir");
        std::fs::write(dir.join(name), bytes).expect("write seed");
    };

    for t in [1usize, 2, 5] {
        put(
            "commitment_decode",
            &format!("seed-commitment-t{t}.bin"),
            &Poly::random(t, &mut rng).commitment().to_bytes(),
        );
    }
    for i in 0..3 {
        put(
            "signature_decode",
            &format!("seed-g2-{i}.bin"),
            &SignatureShare::random_for_test(&mut rng).to_bytes(),
        );
    }
    let p = Poly::random(2, &mut rng);
    for x in 1..4u64 {
        put(
            "scalar_decode",
            &format!("seed-scalar-{x}.bin"),
            &scalar_to_bytes(&p.evaluate(x)),
        );
    }
    for i in 0..3u8 {
        let mut b = vec![1u8]; // INVOICE_COMMITMENT_VERSION
        b.extend_from_slice(&[i; 32]);
        b.extend_from_slice(&[i.wrapping_add(1); 32]);
        put(
            "invoice_commitment_decode",
            &format!("seed-invoice-commitment-{i}.bin"),
            &b,
        );
    }

    let (mut sess, commitment) = DkgSession::new(0, 3, 1, &mut rng);
    let share = sess.share_for(1);
    let _ = &mut sess;
    let msgs = [
        Message::DkgCommitment {
            from: 0,
            commitment,
        },
        Message::DkgShare {
            from: 0,
            to: 1,
            share,
        },
    ];
    for (i, m) in msgs.iter().enumerate() {
        put(
            "wire_message_json",
            &format!("seed-node-msg-{i}.json"),
            &serde_json::to_vec(m).expect("serialize"),
        );
    }
    put(
        "wire_message_json",
        "seed-notary-notarize.json",
        &serde_json::to_vec(&quorum_audit::wire::NotaryMessage::NotarizeRequest {
            root_hash: [7u8; 32],
        })
        .expect("serialize"),
    );

    let mut log = MerkleLog::new();
    for i in 0..6u8 {
        log.append(&[i; 8]);
    }
    for i in [0u64, 3, 5] {
        let proof = log.prove(i).expect("leaf exists");
        put(
            "merkle_proof_json",
            &format!("seed-proof-{i}.json"),
            &serde_json::to_vec(&proof).expect("serialize"),
        );
    }

    let mut alog = AuditLog::default();
    for i in 0..4u64 {
        let e = alog.propose_next(AuditEvent {
            invoice_id: format!("inv-{i}"),
            actor: "a".into(),
            action: "invoice_registered".into(),
            timestamp_unix_ms: i,
        });
        let _ = alog.try_append(e);
    }
    put(
        "audit_log_json",
        "seed-log-4.json",
        &serde_json::to_vec(&alog).expect("serialize"),
    );
    if let Some(e) = alog.entries.first() {
        put(
            "audit_log_json",
            "seed-entry-0.json",
            &serde_json::to_vec(e).expect("serialize"),
        );
    }
}
